import{_ as o,o as a,c as i,a2 as t}from"./chunks/framework.BN2sqjC1.js";const u=JSON.parse('{"title":"ADR-0052 — Rebrand da «MemoBrain Notes» a «Clarae notanda» (M17)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0052-rebrand-clarae-notanda.md","filePath":"adr/0052-rebrand-clarae-notanda.md"}'),d={name:"adr/0052-rebrand-clarae-notanda.md"};function c(n,e,r,l,s,m){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-0052-—-rebrand-da-«memobrain-notes»-a-«clarae-notanda»-m17" tabindex="-1">ADR-0052 — Rebrand da «MemoBrain Notes» a «Clarae notanda» (M17) <a class="header-anchor" href="#adr-0052-—-rebrand-da-«memobrain-notes»-a-«clarae-notanda»-m17" aria-label="Permalink to &quot;ADR-0052 — Rebrand da «MemoBrain Notes» a «Clarae notanda» (M17)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata (2026-11-16, decisione dell&#39;owner); recepita in <code>Specifications.md</code> v1.7 (2026-11-16); piano approvato dall&#39;owner il 2026-11-13; eseguita in M17, F0-F6 fatte il 2026-11-13; uscita come 1.5.0 (pubblicata come 1.5.1). La fase 1 della cartella <code>.memobrain/</code> («mai cancellazioni») è emendata da <a href="./0059-pulizia-cartella-configurazione-legacy-e-zip-coerente.html">ADR-0059</a></td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.7 (2026-11-16): nome del prodotto e identificatori in tutto lo spec (intestazione, §1.1…§4.5, C.2, C.4), con le eccezioni di ADR-0052 (etichette crittografiche congelate, dati e client della 1.x, registro delle revisioni e righe storiche di C.4); nota sulle etichette congelate in §3.8.2; riga <code>features.config_dir_v2</code> in §2.6.6</td></tr><tr><td><strong>Data</strong></td><td>2026-11-13</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>Intestazione e §1.1 (nome del prodotto); §1.3 e D-08 (client e audience OIDC, schema URL); §1.6 e §1.7 (binari, core WASM, dati nel browser); §2.1 e §2.5 (cartella di configurazione del vault); §2.7 (formato <code>.excalidraw</code>); §3.3.1 (realm, client, ruoli); §3.4.2, §3.4.5 e §3.4.6 (path esclusi, scope di sync); §3.6 (gRPC); §3.8.2 e §3.8.3 (etichette crittografiche, <strong>invariate</strong>); §4.1–§4.5 (struttura del monorepo); V-05 e A-04 (Keycloak, una realm)</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>sì → richiede l&#39;aggiornamento di <code>Specifications.md</code> da parte dell&#39;owner: l&#39;elenco puntuale è nella sezione «Sostituzioni da riportare in <code>Specifications.md</code>» di questo ADR</td></tr><tr><td><strong>Superfici</strong></td><td>desktop (client Wails: dati locali, keychain, schema URL, cartella <code>.memobrain/</code>; prove: <code>go test -race</code>, <code>task test-desktop-e2e</code> con i casi C9) · workbench web (storage del browser, core WASM; prove: <code>task test-wasm</code>, <code>task e2e</code>, <code>yarn workspace @clarae/web run e2e:workbench-ui</code>, righe di <code>task parity</code>) · console (marchio, stile; prove: axe, <code>task e2e</code>) · cloud (OIDC, gRPC, bucket, advisory lock, Helm, immagine; prove: <code>task test-integration</code>, <code>task helm-check</code>, <code>task docker-build</code>)</td></tr></tbody></table><p><strong>Aggiornamento 2026-11-15 (decisione dell&#39;owner).</strong> Le rimozioni che questo ADR fissa alla <strong>1.6</strong> (advisory lock col nome vecchio, immagine pubblicata anche come <code>memobrain-cloud</code>, default acceso di <code>features.config_dir_v2</code>) passano alla <strong>1.7</strong>: la 1.6.0 (M18, ADR-0053 e ADR-0054) non le tocca. Il testo qui sotto è lo storico della decisione e dice ancora «1.6»: dove lo dice, per queste tre voci leggete «1.7». La <strong>2.0</strong> non cambia. I motivi di <code>scripts/rebrand/allowlist.tsv</code>, la guida di migrazione e CONTRIBUTING sono già allineati.</p><p><strong>Aggiornamento 2026-11-15, 1.7.0 (M19): le tre rimozioni sono eseguite.</strong> Nella 1.7.0 (sessioni <code>[M19-R1]</code>, <code>[M19-R2]</code>, <code>[M19-R3]</code>) il cloud prende un solo advisory lock per blob, quota degli upload ed export, <code>clarae.&lt;tipo&gt;:&lt;id&gt;</code>; la release pubblica solo <code>ghcr.io/&lt;owner&gt;/clarae-cloud</code>; <code>features.config_dir_v2</code> è acceso per default. Tre conseguenze da sapere. <strong>(R1)</strong> Un pod 1.4 o precedente non deve mai girare insieme a un pod 1.7 o successivo sullo stesso database, perché non si escluderebbero più: da una 1.4 o precedente si passa per la 1.5 o la 1.6 e solo dopo alla 1.7 (1.5 e 1.6 convivono sia con la 1.4 sia con la 1.7); il ritorno alla 1.4.0 resta possibile solo se nessun pod 1.7 è in esecuzione. <strong>(R2)</strong> Chi ha in Compose <code>MEMOBRAIN_IMAGE</code> o <code>CLARAE_IMAGE</code>, o in Helm <code>image.repository</code>, che punta a <code>memobrain-cloud</code> deve cambiarlo in <code>clarae-cloud</code> prima della 1.7: non esiste un tag <code>memobrain-cloud:1.7.x</code>; i tag 1.5 e 1.6 con il vecchio nome restano nel registry. <strong>(R3)</strong> Correzione rispetto al piano: lo spostamento delle impostazioni parte solo dopo che il client ha letto un profilo del server, fresco o in cache. Con il default acceso, una configurazione ancora vuota si leggerebbe come «acceso» e sposterebbe le impostazioni prima che un&#39;organizzazione che ha spento la chiave apposta avesse voce. Il cloud distribuisce il default del proprio schema: un cloud 1.7 manda <code>true</code>, uno 1.5 o 1.6 <code>false</code>, quindi un client 1.7 contro un cloud più vecchio non sposta nulla. Chi amministra aggiorna prima i dispositivi dei vault collegati e poi il cloud, o imposta <code>features.config_dir_v2</code> a <code>false</code> finché non lo sono. Il resto (2.0) non cambia. Il testo sopra e sotto resta lo storico della decisione. Ordine di aggiornamento e dettagli in <a href="./../admin-guide/migrazione-clarae.html"><code>docs/admin-guide/migrazione-clarae.md</code></a>.</p><p><strong>Aggiornamento 2026-11-16 (decisione dell&#39;owner): accettata.</strong> L&#39;owner accetta l&#39;ADR e dispone che <code>Specifications.md</code> v1.7 lo recepisca con la nomenclatura <em>Clarae notanda</em>, <code>clarae</code> e <code>.clarae/</code> in tutto lo spec; restano <code>memobrain</code> solo le etichette crittografiche congelate (<code>memobrain/v1/*</code>, <code>memobrain/v2/*</code>) e i riferimenti ai dati e ai client della 1.x. La sezione «Sostituzioni da riportare in <code>Specifications.md</code>» è la base; i numeri di riga si riferiscono alla v1.5 e vanno ricalcolati sulla v1.6 (<code>command grep -n -i memobrain Specifications.md</code>). La sintesi con le eccezioni è in <a href="./../spec-v1.7-proposta.html"><code>../spec-v1.7-proposta.md</code></a>. <strong>Emendamento:</strong> <a href="./0059-pulizia-cartella-configurazione-legacy-e-zip-coerente.html">ADR-0059</a> (accettata lo stesso giorno) toglie la regola «mai cancellazioni» della fase 1 della cartella <code>.memobrain/</code>: dalla 1.7.2 la pulizia cancella solo ciò che <code>.clarae/</code> ha già o che è un duplicato, e manda nel cestino del vault la copia legacy diversa; il testo sopra e sotto resta lo storico della decisione.</p><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>Il prodotto cambia nome e aspetto: da «MemoBrain Notes» a <strong>«Clarae notanda»</strong>, con il payoff <strong>«Your knowledge, carefully preserved in its clarity.»</strong> e una nuova palette. Le funzionalità restano invariate.</p><p>Il nome non è solo testo di interfaccia. Il prodotto è già rilasciato (CHANGELOG da 1.0.0 a 1.4.0 al momento della decisione; il rename esce nella 1.5.0) e il nome è scritto in dati persistiti: vault degli utenti (cartella <code>.memobrain/</code>, chiavi nei file <code>.excalidraw</code>, marker nei file Marp), keychain del sistema operativo, cartella dati dell&#39;app, schema URL registrato dagli installer, storage del browser (OPFS, IndexedDB, Web Lock), realm Keycloak, client e ruoli, bucket S3, advisory lock di PostgreSQL, servizio gRPC e artefatti di rilascio. Il censimento fatto per il piano (F0) conta il nome in 925 file su 2274, circa 4.350 occorrenze, e in 41 percorsi.</p><p>Il rename precedente, da «Nodus» a «MemoBrain Notes» (<a href="./../release/rebrand-inventory.html"><code>docs/release/rebrand-inventory.md</code></a>), fu eseguito <strong>prima del primo rilascio</strong>: non esistevano installazioni, vault o token da preservare, quindi bastò una sostituzione meccanica, senza alias. Oggi non è più vero: un client 1.4.0 e un cloud già installato devono continuare a funzionare, e nessun vault, bookmark, sessione o chiave di un vault E2EE deve andare perso.</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><h3 id="_1-nome-marchio-e-identificatori" tabindex="-1">1. Nome, marchio e identificatori <a class="header-anchor" href="#_1-nome-marchio-e-identificatori" aria-label="Permalink to &quot;1. Nome, marchio e identificatori&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Voce</th><th>Vecchio</th><th>Nuovo</th></tr></thead><tbody><tr><td>Nome visualizzato (UI, installer, documentazione)</td><td>«MemoBrain Notes»</td><td>«Clarae notanda»</td></tr><tr><td>Identificatori (slug, percorsi, chiavi, binari, realm, client, chart, bucket, scope npm, package proto)</td><td><code>memobrain</code> (kebab, snake e punto come prima)</td><td><code>clarae</code></td></tr><tr><td>Identificatori in PascalCase</td><td><code>Memobrain</code></td><td><code>Clarae</code></td></tr><tr><td>Variabili d&#39;ambiente</td><td><code>MEMOBRAIN_*</code></td><td><code>CLARAE_*</code></td></tr><tr><td>Scope npm</td><td><code>@memobrain/*</code></td><td><code>@clarae/*</code></td></tr><tr><td>ID inverso dell&#39;app (bundle id)</td><td><code>dev.memobrain.desktop</code></td><td><code>dev.clarae.desktop</code></td></tr><tr><td>Schema URL</td><td><code>memobrain://</code></td><td><code>clarae://</code></td></tr><tr><td>Cartella di configurazione del vault</td><td><code>.memobrain/</code></td><td><code>.clarae/</code></td></tr><tr><td>Cartella dati dell&#39;app</td><td><code>MemoBrain Notes</code></td><td><code>Clarae notanda</code></td></tr><tr><td>Payoff</td><td>(assente)</td><td>«Your knowledge, carefully preserved in its clarity.» (non si traduce: stesso testo in <code>en</code> e <code>it</code>)</td></tr><tr><td>Versione</td><td>1.4.0</td><td><strong>1.5.0</strong>; il flag della cartella di configurazione passa ad acceso nella 1.6, il resto della compatibilità con la 1.x si toglie nella 2.0</td></tr></tbody></table><p>Palette: Deep Navy <code>#102B3A</code>, Teal <code>#159992</code>, Mint <code>#72C9BD</code>, Mist <code>#E9F0EF</code>, White <code>#FFFFFF</code>, applicata a desktop e console web da F5. Il logo è ridisegnato in vettoriale a partire da <code>assets/clarae.png</code> (F4). I valori dei token, i contrasti e gli accenti dell&#39;utente sono definiti nelle fasi F4 e F5 di M17 (<code>docs/roadmap.md</code>) e non in questo ADR.</p><p>Il magic byte <code>NDS1</code> del formato E2EE resta com&#39;è: è un identificatore di formato, non il nome del prodotto (già deciso nel rename precedente).</p><h3 id="_2-regola-di-compatibilita-migrazione-automatica" tabindex="-1">2. Regola di compatibilità: migrazione automatica <a class="header-anchor" href="#_2-regola-di-compatibilita-migrazione-automatica" aria-label="Permalink to &quot;2. Regola di compatibilità: migrazione automatica&quot;">​</a></h3><p><strong>Nessuna perdita di dati e nessuna azione manuale dell&#39;utente per vault, bookmark, sessione e chiavi E2EE; client 1.4.0 e cloud esistenti continuano a funzionare.</strong> Il codice nuovo scrive i nomi nuovi e legge anche i vecchi; dove un client 1.4.0 e uno nuovo condividono dati (vault collegati, cloud) il vecchio nome resta valido per il tempo della transizione.</p><p>Ogni occorrenza di <code>memobrain</code> che resta nel repository appartiene a <strong>una sola di tre classi</strong>.</p><p><strong>2.1 Congelato per sempre.</strong> Solo le etichette crittografiche dei vault. Sono l&#39;input di HKDF e l&#39;AAD di AES-GCM: cambiarle rende indecifrabili i vault privati (E2EE) già creati. Nomi esatti, verificati sul codice:</p><table tabindex="0"><thead><tr><th>Etichetta</th><th>Uso</th><th>Go</th><th>TypeScript</th></tr></thead><tbody><tr><td><code>memobrain/v1/path-enc</code></td><td>HKDF info della chiave di cifratura dei path</td><td><code>shared/go/vaultcrypto/keys.go:36</code></td><td><code>packages/vaultcrypto-web/src/keys.ts:16</code></td></tr><tr><td><code>memobrain/v1/path-key</code></td><td>HKDF info della chiave HMAC dei path</td><td><code>shared/go/vaultcrypto/keys.go:37</code></td><td><code>packages/vaultcrypto-web/src/keys.ts:17</code></td></tr><tr><td><code>memobrain/v1/file</code></td><td>HKDF info della chiave del singolo file (<code>file_id ‖ salt</code>)</td><td><code>shared/go/vaultcrypto/keys.go:38</code></td><td><code>packages/vaultcrypto-web/src/keys.ts:18</code></td></tr><tr><td><code>memobrain/v1/recovery-kek</code></td><td>HKDF info della KEK derivata dalla recovery key</td><td><code>shared/go/vaultcrypto/keys.go:39</code></td><td><code>packages/vaultcrypto-web/src/keys.ts:19</code></td></tr><tr><td><code>memobrain/v1/recovery-checksum</code></td><td>prefisso dell&#39;hash di controllo della recovery key</td><td><code>shared/go/vaultcrypto/keys.go:212</code></td><td><code>packages/vaultcrypto-web/src/keys.ts:148</code></td></tr><tr><td><code>memobrain/v2/envelope</code></td><td>AAD dell&#39;envelope v2 della VMK (<a href="./0034-envelope-aad.html">ADR-0034</a>)</td><td><code>shared/go/vaultcrypto/keys.go:284</code></td><td><code>packages/vaultcrypto-web/src/keys.ts:228</code></td></tr><tr><td><code>memobrain/v2/path</code></td><td>AAD del token di path <code>enc2</code> (<a href="./0042-path-token-legato-al-file.html">ADR-0042</a>)</td><td><code>shared/go/vaultcrypto/path.go:31</code></td><td><code>packages/vaultcrypto-web/src/path.ts:10</code></td></tr></tbody></table><p>Le stesse stringhe compaiono anche nei test dei due pacchetti (<code>shared/go/vaultcrypto/vaultcrypto_test.go</code>) e nel documento vivo che descrive il formato (<code>docs/security/crypto-design.md</code>): restano com&#39;erano e sono nell&#39;allowlist. Un test vector che fallisse dopo il rename è un errore del rename, non un test da aggiornare.</p><p><strong>2.2 Legacy transitorio.</strong> Percorsi di compatibilità: il codice che legge o serve ancora il vecchio nome perché esistono dati e client 1.4.0. Ogni voce è nell&#39;allowlist con una <strong>release di rimozione</strong> (le eccezioni sono sotto la tabella); quando la release arriva la voce si toglie dal codice e dall&#39;allowlist nello stesso commit.</p><table tabindex="0"><thead><tr><th>Ambito</th><th>Nome legacy</th><th>Comportamento nella 1.5.0</th><th>Rimozione</th></tr></thead><tbody><tr><td>Cartella del vault, in due fasi</td><td><code>.memobrain/</code> e <code>.memobrain-tmp-*</code></td><td>Regole di path a doppio nome (<code>ConfigDir</code>, <code>LegacyConfigDirs</code>, <code>IsConfigPath</code>, <code>IsTmpName</code>). <strong>Fase 1:</strong> all&#39;apertura la parte locale (<code>index.db*</code>, <code>sync.db*</code>, <code>cache/</code>, <code>snapshots/</code>, <code>workspace*.json</code>) si sposta in <code>.clarae/</code> (<code>vaultdir.Ensure</code>), in modo idempotente, vince <code>.clarae</code>, mai cancellazioni; nei vault non collegati si spostano anche le impostazioni (<code>AdoptSettings</code>); un vault che si collega al cloud con il flag spento rimette le sue impostazioni sincronizzate nella cartella vecchia (<code>vault.FS.ShelveConfig</code>). <strong>Fase 2:</strong> le impostazioni sincronizzate dei vault collegati si leggono da <code>.clarae/X</code>, poi <code>.memobrain/X</code> (<code>vault.FS.ReadConfig</code>), si scrivono dove il file già si trova, e si spostano solo con il flag <code>features.config_dir_v2</code> (spento nella 1.5.0). Pull e bootstrap non scrivono mai un path che <code>IsExcluded</code> esclude</td><td>flag acceso in 1.6; doppio nome rimosso in 2.0</td></tr><tr><td>File <code>.excalidraw</code></td><td>chiave <code>customData.memobrain</code></td><td>Scrive <code>clarae</code> e legge entrambe, elemento per elemento: un elemento passa alla chiave nuova solo quando uno strumento lo riscrive, le impostazioni del disegno al salvataggio</td><td>nessuna: si legge finché esistono file della 1.x (non c&#39;è una conversione in blocco)</td></tr><tr><td>Presentazioni Marp</td><td><code>memobrain: hidden</code>, <code>memobrain-loop</code></td><td>Legge <code>clarae|memobrain: hidden</code> e <code>clarae-loop ?? memobrain-loop</code> (idem <code>-notes</code>), scrive i nuovi; un&#39;impostazione scritta toglie la vecchia nella stessa modifica</td><td>nessuna: si legge finché esistono file della 1.x (non c&#39;è una conversione in blocco)</td></tr><tr><td>Keychain</td><td>servizio <code>memobrain</code> nel keychain del sistema operativo</td><td>Legge dal vecchio servizio (<code>internal/ossecret</code>), copia nel nuovo, scrive nel nuovo e toglie il vecchio, <code>Delete</code> su tutti</td><td>2.0</td></tr><tr><td>Cartella dati</td><td><code>MemoBrain Notes</code></td><td>Al primo avvio rinomina in <code>Clarae notanda</code> con rename atomico, dopo una sonda di quiete su <code>app.db</code> (dialogo «chiudi la vecchia app» se è in esecuzione, e l&#39;app non parte), e riscrive i <code>recent_vaults.path</code>; su Windows sposta anche il profilo WebView2 in <code>&lt;cartella dati&gt;\\webview</code></td><td>2.0</td></tr><tr><td>Schema URL</td><td><code>memobrain://</code></td><td>Ancora registrato e accettato accanto a <code>clarae://</code>; il redirect OIDC ricade sul vecchio URI se il realm rifiuta il nuovo</td><td>2.0</td></tr><tr><td>Storage del browser</td><td>cartelle OPFS per <code>accountKey</code>, IndexedDB <code>memobrain-device</code>, marker dei vault, Web Lock <code>memobrain-workbench</code>, canali, preferenze (tema, lingua, strumenti recenti); <strong>non</strong> la cartella dati del core (<code>/memobrain/data</code>) né le chiavi dei database nel pool SQLite</td><td>Migrazione sotto lock; la pagina nuova prende <strong>entrambi</strong> i Web Lock e ascolta entrambi i canali, così non convive mai con una scheda vecchia; preferenze in lettura doppia. La cartella dati del core e le chiavi dei database restano com&#39;erano nei profili 1.x (vedi «Esito dell&#39;implementazione»)</td><td>2.0</td></tr><tr><td>gRPC</td><td>package <code>memobrain.v1</code></td><td>Il proto <code>clarae.v1</code> (<code>api/proto/clarae/v1</code>) è il nuovo; <code>memobrain.v1</code> resta come proto <code>legacy</code> servito dallo stesso handler, con route dell&#39;ingress per entrambi; il client nuovo contro un cloud vecchio ricade sull&#39;SSE già esistente</td><td>2.0</td></tr><tr><td>Advisory lock di PostgreSQL</td><td>chiavi con il vecchio nome</td><td>Nomi nuovi; il vecchio lock si prende <strong>prima</strong> del nuovo per una release, perché durante un aggiornamento a rotazione girano repliche vecchie e nuove</td><td>1.6</td></tr><tr><td>Variabili d&#39;ambiente</td><td><code>MEMOBRAIN_*</code></td><td><code>CLARAE_X</code> vince; <code>MEMOBRAIN_X</code> vale ancora, con un warning (<code>shared/go/envcompat</code>). Sono cinque le variabili lette a runtime (<code>DATA_DIR</code>, <code>UPDATES</code>, <code>AUTH_REDIRECT</code>, <code>DEFAULT_SERVER_URL</code> del desktop, <code>ALLOW_PLACEHOLDER_SECRETS</code> del cloud) e cinque quelle di Compose (<code>HOST</code>, <code>SITE</code>, <code>IMAGE</code>, <code>VERSION</code>, <code>ALLOW_PLACEHOLDER_SECRETS</code>). Le variabili solo di test, perf e build si rinominano senza alias</td><td>2.0</td></tr><tr><td>Issuer OIDC</td><td><code>/realms/memobrain</code> e i suoi default</td><td><code>nameDefaults(issuer)</code>: se l&#39;issuer è <code>/realms/memobrain</code> valgono audience, AZP, client e bucket vecchi, altrimenti i nuovi</td><td>2.0</td></tr><tr><td>Ruolo admin</td><td><code>memobrain-admin</code></td><td><code>OIDC_ADMIN_ROLES</code>, default <code>clarae-admin,memobrain-admin</code>: vale il doppio ruolo; <code>SetAdmin</code> assegna il primo ruolo che il realm ha e toglie tutti quelli posseduti</td><td>2.0</td></tr><tr><td>Bucket S3</td><td>bucket con il nome vecchio</td><td>Il cloud <strong>rifiuta di partire</strong> se il bucket di default manca ma esiste quello vecchio (la 1.x lo avrebbe creato vuoto)</td><td>2.0</td></tr><tr><td>Helm</td><td>selector e <code>nameOverride</code> <code>memobrain</code></td><td>Chart <code>clarae</code> con <code>nameOverride</code>/<code>fullnameOverride</code> nuovi; i selector sono immutabili, quindi per l&#39;upgrade in-place <code>--set nameOverride=memobrain</code></td><td>2.0</td></tr><tr><td>Immagine del cloud</td><td>nome <code>memobrain</code></td><td>Pubblicata sotto i due nomi per una release</td><td>1.6</td></tr><tr><td>Installer desktop</td><td>app, pacchetti <code>.deb</code> e AppImage <code>memobrain</code></td><td>NSIS rimuove la vecchia installazione senza eseguirne il disinstallatore (cancellerebbe i dati del WebView); con l&#39;app vecchia aperta chiede di chiuderla, e un&#39;installazione silenziosa si ferma con codice 5; <code>nfpm.yaml</code> con <code>replaces</code> e <code>conflicts: [memobrain]</code></td><td>2.0</td></tr></tbody></table><p>Le release di rimozione sono fissate (F6) e coincidono con i motivi delle righe di <code>scripts/rebrand/allowlist.tsv</code>: <strong>1.6</strong> per la cartella di configurazione (il flag passa ad acceso), gli advisory lock e l&#39;immagine con due nomi, <strong>2.0</strong> per il resto. Fanno eccezione la lettura dei file <code>.excalidraw</code> e delle presentazioni Marp della 1.x e l&#39;adozione in sede dell&#39;insieme di dati del browser della 1.3 (<code>storage.ts</code>): servono finché esistono file e profili scritti dalla 1.x, e non hanno una release, perché nessun passo converte in blocco i file di un utente.</p><p><strong>2.3 Storico.</strong> Documenti che descrivono com&#39;erano le cose e non si riscrivono: <code>Specifications.md</code> (finché l&#39;owner non lo aggiorna), le voci passate di <code>CHANGELOG.md</code>, gli ADR 0001–0051, <code>docs/release/rebrand-inventory.md</code>, le note di QA <code>docs/qa/m*-*.md</code> e <code>.claude/roadmap/</code>.</p><h3 id="_3-allowlist-come-contratto-guardia-permanente" tabindex="-1">3. Allowlist come contratto, guardia permanente <a class="header-anchor" href="#_3-allowlist-come-contratto-guardia-permanente" aria-label="Permalink to &quot;3. Allowlist come contratto, guardia permanente&quot;">​</a></h3><p>La regola «ogni <code>memobrain</code> rimasto è in una delle tre classi» è imposta dal codice, non dalla memoria:</p><ul><li><strong><code>scripts/rebrand/allowlist.tsv</code></strong>: una riga per eccezione, <code>classe ⇥ pathspec ⇥ regex ⇥ motivo</code>. Classi: <code>frozen</code> (crittografia, punto 2.1), <code>legacy</code> (compatibilità, punto 2.2, con la release di rimozione nel motivo), <code>fixture</code> (file nel formato vecchio usati dai test, per esempio le <code>.excalidraw</code> di <code>shared/conformance/merge/</code>), <code>history</code> (file interi del punto 2.3), <code>external</code> (URL del repository GitHub, che non cambia con il prodotto) e <code>tool</code> (gli script del rename, che nominano ciò che cercano). Il 2026-11-13 ha 84 righe.</li><li><strong><code>scripts/rebrand/check.mjs</code></strong> con il suo test (<code>lib.test.mjs</code>), e il task <strong><code>lint-brand</code></strong> come primo passo di <code>task lint</code> (quindi di <code>task ci</code>): fallisce su ogni riga o percorso con <code>memobrain</code> fuori allowlist <strong>e</strong> su ogni voce dell&#39;allowlist che non corrisponde più a nulla. L&#39;elenco può quindi solo accorciarsi: un&#39;eccezione non si aggiunge «per sicurezza», e quando una voce legacy viene rimossa dal codice la guardia obbliga a toglierla anche dall&#39;elenco.</li><li>Il rename meccanico è stato eseguito una volta da <code>scripts/rebrand/run.sh</code> (F1): <code>rename.mjs</code> rinomina contenuti e percorsi tranne dove l&#39;allowlist lo vieta, poi formattazione, <code>yarn install</code>, <code>task gen</code> e la guardia. Il commit del passo meccanico (860 file) è separato da quelli della compatibilità.</li></ul><p>Il payoff non passa dal rename meccanico (le sue dieci occorrenze hanno punteggiatura diversa): si inserisce in F4.</p><h3 id="_4-manifest-di-update-e-chiave-di-sviluppo-si-rinominano" tabindex="-1">4. Manifest di update e chiave di sviluppo: si rinominano <a class="header-anchor" href="#_4-manifest-di-update-e-chiave-di-sviluppo-si-rinominano" aria-label="Permalink to &quot;4. Manifest di update e chiave di sviluppo: si rinominano&quot;">​</a></h3><p>Il contesto di firma del manifest (<code>shared/go/updatemanifest/manifest.go:40</code>, ora <code>&quot;clarae-update-manifest-v1\\n&quot;</code>) e il seed della chiave di sviluppo (<code>apps/desktop/internal/updater/key.go:27</code> e <code>tools/release/main.go:295</code>, ora <code>&quot;clarae-development-update-key-NOT-FOR-PRODUCTION&quot;</code>) <strong>sono rinominati</strong> (B6), a differenza di quanto si pensava all&#39;inizio del piano. Non è una deroga alla classe «congelato», perché non cambia nessun dato che un utente possiede. Verificato il 2026-11-13:</p><ul><li>le otto release pubblicate su GitHub (da v1.2.3 a v1.4.0; le versioni precedenti hanno tag ma nessuna release pubblica) contengono solo <code>.dmg</code>, <code>.AppImage</code>, <code>.deb</code>, <code>.exe</code> e <code>SHA256SUMS</code>: <strong>nessuna ha un <code>manifest.json</code></strong> né una firma del manifest;</li><li>l&#39;updater non è attivo in nessuna build pubblicata: il <code>release.yml</code> di ciascuno degli otto tag imposta <code>ALLOW_UNSIGNED_UPDATES: &#39;1&#39;</code> (<code>.github/workflows/release.yml:120</code>) e non nomina alcun manifest;</li><li>il repository non ha la variabile <code>UPDATE_PUBLIC_KEY</code> né segreti di firma (<code>gh variable list</code> e <code>gh secret list</code> vuoti).</li></ul><p>Quindi nessun client in circolazione verifica una firma con il vecchio contesto. Se una release futura firmasse un manifest con il nuovo contesto, i client 1.4.0 lo rifiuterebbero, ma non ne esistono di abilitati ad accettarlo. Il controllo è ripetibile con <code>gh release view &lt;tag&gt; --json assets</code> e <code>git show &lt;tag&gt;:.github/workflows/release.yml</code>.</p><h3 id="_5-fasi-e-versione" tabindex="-1">5. Fasi e versione <a class="header-anchor" href="#_5-fasi-e-versione" aria-label="Permalink to &quot;5. Fasi e versione&quot;">​</a></h3><p>M17 (<code>docs/roadmap.md</code>, §13-decies) esegue il piano in sei fasi: F0 preparazione (con il nome vecchio), F1 rename meccanico e guardia, F2 compatibilità lato client (C1…C9), F3 compatibilità di cloud, deploy e release (B1…B7), F4 marchio, F5 stile, F6 documentazione. L&#39;ordine è F0 → F1 → (F2 ‖ F3 ‖ F4 ‖ F5) → F6. La versione è <strong>1.5.0</strong> (decisione dell&#39;owner; il piano approvato diceva 2.0.0), perché il cambio di nome e le migrazioni rompono la continuità dei percorsi di installazione: la 1.5 è questa release, la <strong>1.6</strong> accende <code>features.config_dir_v2</code> e toglie i doppi advisory lock e la doppia immagine, la <strong>2.0</strong> toglie il resto della compatibilità con la 1.x.</p><h3 id="esito-dell-implementazione-2026-11-13" tabindex="-1">Esito dell&#39;implementazione (2026-11-13) <a class="header-anchor" href="#esito-dell-implementazione-2026-11-13" aria-label="Permalink to &quot;Esito dell&#39;implementazione (2026-11-13)&quot;">​</a></h3><p>Le sei fasi sono eseguite sul ramo <code>rebrand/clarae</code> (un commit per work package, con la sigla <code>[M17-…]</code>; stato per onda in <code>docs/roadmap.md</code>, §13-decies). Ciò che il codice fa, e dove la decisione sopra è stata precisata o corretta:</p><ul><li><strong>Impostazioni sincronizzate di un vault che si collega.</strong> Un vault non collegato adotta le sue impostazioni in <code>.clarae/</code> (fase 1). Se poi viene collegato al cloud, un client 1.x dello stesso vault non le vedrebbe: <code>Manager.Link</code> e <code>LinkExisting</code> chiamano <code>vault.FS.ShelveConfig</code>, che con il flag spento sposta nella cartella vecchia le impostazioni che sincronizzano (un file che la cartella vecchia ha già resta dov&#39;è, e ciò che non sincronizza non si muove). Con il flag acceso non fa nulla. Non era nel piano; la prova è un caso del test a due dispositivi di C9.</li><li><strong>Guardia in pull e bootstrap.</strong> <code>sync/pull.go</code> (<code>skipExcluded</code>) non scrive mai un path remoto che <code>pathrules.IsExcluded</code> esclude (database, cache, layout del dispositivo, temporanei, residui del sistema operativo): in un vault privato il cloud non legge i path e un client vecchio può aver caricato un <code>sync.db</code>. La modifica si conta come applicata, quindi il cursore avanza, e si registra un avviso una volta per esecuzione e per file.</li><li><strong>Browser: cosa non si sposta, e perché.</strong> Si migrano le cartelle OPFS dell&#39;account, i marker, la registrazione del dispositivo e le preferenze. <strong>La cartella dati del core (<code>&lt;fs&gt;/memobrain/data</code>) e le chiavi dei database nel pool SQLite non si spostano</strong> per un profilo 1.x: nel browser i database del core non sono file di quella cartella ma voci del pool <code>opfs-sahpool</code>, salvate sotto il path con cui il core le ha aperte (il proprio <code>app.db</code>, lo stato di sync di ogni mount, <code>index.db</code> e <code>sync.db</code> di un vault); il pool non può rinominare una voce e una copia non è atomica (un crash lascerebbe lo stato di sync a metà). Spostare la cartella, come nel primo tentativo di C7, avviava il core dove non trovava né il suo database né lo stato dei mount, con le modifiche non caricate. <code>web/src/workbench/storage.ts</code> (<code>dataDirOf</code>) avvia il core sulla cartella che il profilo ha già e dà il nome nuovo solo a un profilo nuovo; <code>apps/desktop/internal/vaultdir/dbpath_js.go</code> tiene per un database la chiave con cui esiste (la corrente se c&#39;è, altrimenti quella della cartella di configurazione vecchia, altrimenti la corrente). Sono path interni che nessuno vede, come le chiavi del pool stesse.</li><li><strong>Cloud: nomi che seguono il realm.</strong> <code>nameDefaults(issuer)</code> decide audience, AZP, client, realm, bucket e namespace delle metriche; un valore esplicito vince sempre. <code>OIDC_ADMIN_ROLES</code> ha come default <code>clarae-admin,memobrain-admin</code> (<code>services/cloud/internal/config/config.go</code>, <code>auth.DefaultAdminRoles</code>): un&#39;installazione fatta per la 1.x non deve rinominare il ruolo. Il realm esportato nuovo ha il nome <code>${KC_REALM:clarae}</code> e i due redirect.</li><li><strong>Compose: quattro righe obbligatorie</strong> (<code>COMPOSE_PROJECT_NAME</code>, <code>POSTGRES_USER</code>, <code>POSTGRES_DB</code>, <code>KC_REALM</code>), non tre come nel piano: anche il nome dell&#39;utente PostgreSQL è fissato alla creazione del volume.</li><li><strong>Rename meccanico:</strong> <code>scripts/rebrand/rename.mjs</code> pilotato da <code>run.sh</code>, non il solo <code>run.sh</code> descritto dal piano; <code>rename-module</code> è stato rimosso in F1, non in F0. In F5 non è stato introdotto il token <code>--accent-fill</code> ipotizzato: i link e i pulsanti pieni usano <code>--accent</code> (tonalità più scura del Teal) e il Teal vero è <code>--accent-bright</code>.</li></ul><p><strong>Non provato</strong> (lo dicono anche il CHANGELOG e la roadmap): il dialogo «chiudi la vecchia app» e la rinomina rifiutata su Windows; l&#39;installer Windows sopra una 1.x, con l&#39;app aperta e in modalità silenziosa (il test compila lo script con <code>makensis</code> dove c&#39;è, e non lo esegue); il <code>.deb</code> sopra il pacchetto vecchio; il portachiavi vero dei tre sistemi (i test usano un portachiavi finto); <strong>lo spostamento del profilo del WebView su macOS e Linux, che il codice non fa</strong> (lo fa solo su Windows), quindi ciò che il WebView tiene per sé, per esempio l&#39;elenco degli strumenti recenti di Excalidraw, può ripartire vuoto; l&#39;interoperabilità con un&#39;app 1.4.0 vera (C9 simula il client vecchio scrivendo sul disco); la migrazione del profilo di un browser usato per mesi con la 1.4; l&#39;aspetto sulle superfici reali (icone nel Dock e nel Finder, favicon, PWA) e l&#39;approvazione del marchio da parte dell&#39;owner.</p><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Cambiare solo il nome visualizzato e tenere gli identificatori <code>memobrain</code></strong> — la più semplice e senza rischi per i dati, ma lascia il vecchio nome in percorsi, bundle id, schema URL, realm e pacchetti, visibili a chi installa e amministra; l&#39;owner ha chiesto di cambiare anche questi («rinomina tutto»).</li><li><strong>Rename meccanico senza compatibilità, come in «Nodus» → «MemoBrain Notes»</strong> — scartata: il prodotto è rilasciato, e un rename secco renderebbe illeggibili cartelle <code>.memobrain/</code>, sessioni nel keychain, dati del browser, bucket e realm esistenti, e spezzerebbe i client 1.4.0 collegati a un cloud aggiornato.</li><li><strong>Congelare anche i nomi di protocollo e di formato</strong> (gRPC, advisory lock, chiave Excalidraw, storage del browser, contesto di firma) — era la prima proposta, perché non rinominarli non costa nulla. Scartata dall&#39;owner: si rinominano, con lettura o servizio doppio, e <code>memobrain</code> resta solo nelle etichette crittografiche e nei percorsi legacy elencati.</li><li><strong>Doppio nome permanente (mai rimuovere i percorsi legacy)</strong> — scartata: ogni percorso a doppio nome è codice da mantenere e da provare per sempre; con le release di rimozione e la guardia l&#39;elenco dei vecchi nomi si accorcia fino a lasciare solo il congelato.</li><li><strong>Spostare in un colpo solo anche le impostazioni sincronizzate di <code>.memobrain/</code></strong> — scartata: un client 1.4.0 collegato allo stesso vault non le vedrebbe più e le ricreerebbe, con conflitti. Lo spostamento avviene in due fasi, dietro il flag <code>features.config_dir_v2</code> e sul modello di <code>sync/pathmigrate.go</code>.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><p><strong>Positive.</strong> Il prodotto ha un solo nome nei percorsi, nei pacchetti, nei binari e nell&#39;interfaccia; ogni residuo del vecchio nome è un&#39;eccezione elencata e motivata; la guardia in <code>task ci</code> impedisce di reintrodurlo. I dati degli utenti si migrano da soli.</p><p><strong>Costo accettato.</strong></p><ul><li>Per un periodo il codice ha percorsi a doppio nome (client e cloud) da mantenere e provare; i casi di interoperabilità tra un client 1.4.0 e uno nuovo (flag spento, flag acceso, ricreazione dal client vecchio, vault privato, path escluso remoto, mount legacy) sono in C9.</li><li>Un disegno toccato dal client nuovo non ha più formule modificabili né ordine delle diapositive su un client 1.4.0 (la chiave <code>customData.clarae</code> non è letta dal vecchio); nei merge concorrenti di un <code>.excalidraw</code> possono restare entrambe le chiavi, e il client nuovo le legge tutte e due.</li><li>Le etichette crittografiche restano <code>memobrain</code> per sempre: chi legge il codice di <code>vaultcrypto</code> trova il vecchio nome, e lo troverà documentato in <code>docs/security/crypto-design.md</code>.</li><li>Il bundle id e il nome dell&#39;app cambiano: sul sistema operativo la 1.5.0 è un&#39;app diversa dalla 1.4.0.</li></ul><p><strong>Non automatizzabile.</strong></p><ul><li>L&#39;installazione della 1.5.0 su ogni macchina, perché nessun client ha l&#39;updater attivo, e la rimozione a mano della vecchia app su macOS e del vecchio AppImage.</li><li>Sui realm Keycloak esistenti, l&#39;aggiunta del redirect <code>clarae://auth/callback</code> al client desktop (finché manca, il client ricade sul redirect vecchio).</li><li>Nei <code>.env</code> di Compose esistenti, quattro righe da aggiungere (nome del progetto, utente e database PostgreSQL, realm), descritte nella guida <code>docs/admin-guide/migrazione-clarae.md</code> (B7). In Compose <code>COMPOSE_PROJECT_NAME</code>, <code>POSTGRES_USER</code>, <code>POSTGRES_DB</code> e <code>KC_REALM</code> diventano obbligatori e senza default.</li></ul><p><strong>Da rivedere.</strong> Le release di rimozione sono fissate (1.6 e 2.0); restano senza release la lettura dei file <code>.excalidraw</code> e delle presentazioni Marp della 1.x e l&#39;adozione dell&#39;insieme di dati del browser della 1.3: l&#39;owner può fissarne una (e allora decidere se convertire i file in blocco). Quando l&#39;owner aggiorna <code>Specifications.md</code> l&#39;ADR passa a «accettata» e la tabella dell&#39;indice si allinea. I documenti vivi e la voce 1.5.0 del CHANGELOG sono scritti (F6); <code>CLAUDE.md</code> e il glossario sono dell&#39;owner.</p><h2 id="sostituzioni-da-riportare-in-specifications-md" tabindex="-1">Sostituzioni da riportare in <code>Specifications.md</code> <a class="header-anchor" href="#sostituzioni-da-riportare-in-specifications-md" aria-label="Permalink to &quot;Sostituzioni da riportare in `Specifications.md`&quot;">​</a></h2><p>Elenco per l&#39;owner. <code>Specifications.md</code> <strong>non è stato modificato</strong>: i numeri di riga si riferiscono alla v1.5 attuale (<code>command grep -n -i memobrain Specifications.md</code> dà 96 righe). Tutte le righe con il vecchio nome sono nei gruppi qui sotto, tranne la 1026, che è una cella di tabella a sé.</p><h3 id="sostituzione-semplice" tabindex="-1">Sostituzione semplice <a class="header-anchor" href="#sostituzione-semplice" aria-label="Permalink to &quot;Sostituzione semplice&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tipo</th><th>Da → a</th><th>Righe</th></tr></thead><tbody><tr><td>Nome visualizzato</td><td>«MemoBrain Notes» → «Clarae notanda»</td><td>1 (titolo), 9, 42 (§1.1), 327 (intestazione della matrice §2.2.1)</td></tr><tr><td>Scope npm</td><td><code>@memobrain/*</code> → <code>@clarae/*</code></td><td>134, 157, 277, 282, 537, 579, 636, 673, 712, 1659, 1697, 1731, 1735, 1758, 1762, 1763, 1767, 1769, 1837, 1851, 1942, 1989, 1997, 2003</td></tr><tr><td>Binari, comandi, simboli globali del core</td><td><code>memobrain-core</code>, <code>memobrain-cloud</code>, <code>memobrain-core.wasm</code>, <code>__memobrainCore</code>, <code>__memobrainHost</code> → <code>clarae-…</code></td><td>266, 280, 281, 288, 1686, 1694, 1776, 1851, 1990</td></tr><tr><td>Layout del monorepo (radice, chart, realm, proto)</td><td><code>memobrain/</code> → <code>clarae/</code> (radice), <code>helm/memobrain</code> → <code>helm/clarae</code>, <code>realm-memobrain.json</code> → <code>realm-clarae.json</code>, <code>proto/memobrain/v1/notify.proto</code> → <code>proto/clarae/v1/notify.proto</code></td><td>1638, 1646, 1672, 1673</td></tr><tr><td>URL di esempio degli errori RFC 9457</td><td><code>https://memobrain.example/errors/…</code> → <code>https://clarae.example/errors/…</code></td><td>728 (è un esempio nello spec, non è nel codice né in <code>api/openapi.yaml</code>)</td></tr><tr><td>Variabile solo di test/build</td><td><code>MEMOBRAIN_REQUIRE_BINDINGS</code> → <code>CLARAE_REQUIRE_BINDINGS</code></td><td>1863 (§4.5)</td></tr></tbody></table><h3 id="non-basta-sostituire-periodo-di-doppio-nome-o-nome-che-resta" tabindex="-1">Non basta sostituire: periodo di doppio nome o nome che resta <a class="header-anchor" href="#non-basta-sostituire-periodo-di-doppio-nome-o-nome-che-resta" aria-label="Permalink to &quot;Non basta sostituire: periodo di doppio nome o nome che resta&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Punto dello spec</th><th>Righe</th><th>Cosa scrivere</th></tr></thead><tbody><tr><td><strong>Etichette crittografiche</strong> — §3.8.2 (albero delle chiavi), §3.8.3 (envelope, AAD dei path)</td><td>1536, 1537, 1538, 1547, 1571</td><td><strong>Non sostituire.</strong> Restano <code>memobrain/v1/…</code> e <code>memobrain/v2/…</code>. Aggiungere una nota: «etichette di dominio congelate: il prefisso non segue il nome del prodotto» (ADR-0052). Le sette etichette sono nel punto 2.1 di questo ADR.</td></tr><tr><td><strong>Cartella <code>.memobrain/</code></strong> — §2.1, §2.2.1, §2.5 (<code>history</code>), §2.7.1, §3.4.2, §3.4.5, §3.4.6, §2.8.2, C.4</td><td>299, 340, 341, 352, 353, 354, 361, 482, 613, 616, 618, 619, 630, 666, 1085, 1163, 1196, 1201, 1202, 1203, 1975, 1977, 1978, 1980, 1985, 1995</td><td>Sostituire con <code>.clarae/</code> e descrivere il periodo di transizione: i client leggono anche <code>.memobrain/</code>; la parte locale si sposta all&#39;apertura, le impostazioni sincronizzate dei vault collegati solo con il flag <code>features.config_dir_v2</code> (finché è spento, un vault che si collega al cloud le tiene nella cartella vecchia). Il titolo di <strong>§3.4.6</strong> («Scope di sincronizzazione della cartella <code>.memobrain/</code>») e la tabella 1196–1203 devono nominare entrambe le cartelle. Le righe 1975–1995 sono nel registro degli ADR recepiti (C.4) e descrivono la decisione di allora: lasciarle come storico e aggiungere la nota di ADR-0052.</td></tr><tr><td><strong>Esclusi dal sync</strong> — §3.4.2</td><td>1085, 1984 (C.4)</td><td><code>.memobrain-tmp-*</code> → <code>.clarae-tmp-*</code>, ma i temporanei col vecchio nome (lasciati da un crash di un client 1.4.0) restano esclusi dal sync, dall&#39;indice e dall&#39;elenco: la regola è a doppio nome. Aggiungere <code>.clarae/</code> ai path esclusi e dire che <code>.memobrain/…</code> segue le stesse regole nel periodo di transizione.</td></tr><tr><td><strong>Schema URL</strong> — §1.3 (D-08), §2.2.1 (riga «URI scheme»), §3.3.1, C.2</td><td>208, 209, 372, 373, 681, 1027, 1943</td><td><code>clarae://</code> è lo schema registrato dagli installer; <code>memobrain://</code> è ancora registrato e accettato (link vecchi, redirect OIDC). Il redirect del client <code>…-desktop</code> ha entrambi gli URI e il client ricade sul vecchio se il realm rifiuta il nuovo (D-08, §1.3). La riga 373 (CLI <code>memobrain open</code>, <code>memobrain new</code>, P2) → <code>clarae open</code>, <code>clarae new</code>: voce P2 dello spec.</td></tr><tr><td><strong>Variabile <code>MEMOBRAIN_AUTH_REDIRECT</code></strong> — §1.3</td><td>208</td><td><code>CLARAE_AUTH_REDIRECT</code> ha la precedenza; <code>MEMOBRAIN_AUTH_REDIRECT</code> vale ancora, con un warning.</td></tr><tr><td><strong>Keycloak e audience</strong> — §1.3, §1.6, §2.8, §3.3.1</td><td>186, 203, 267, 642, 1026, 1027, 1028, 1029, 1030, 1031</td><td>Realm, client (<code>…-desktop</code>, <code>…-web</code>, <code>…-api</code>, <code>…-admin-svc</code>), ruoli (<code>…-admin</code>, <code>…-user</code>) e <code>aud</code> passano a <code>clarae…</code>, ma sulle installazioni esistenti vale ancora il vecchio nome: se l&#39;issuer è <code>/realms/memobrain</code> restano audience (<code>memobrain-api</code>), AZP, client e bucket vecchi; il ruolo admin è doppio (<code>OIDC_ADMIN_ROLES</code>). Il realm esportato nuovo è <code>realm-clarae.json</code>, con entrambi i redirect. Tocca anche <strong>V-05</strong> e <strong>A-04</strong> (una realm Keycloak) solo se si vuole citare il nome.</td></tr><tr><td><strong>gRPC</strong> — §3.6</td><td>1466</td><td><code>package clarae.v1;</code>, con una nota: <code>memobrain.v1</code> è servito ancora dallo stesso handler (proto <code>legacy</code>); il client nuovo contro un cloud vecchio ricade sull&#39;SSE.</td></tr><tr><td><strong>Chiave Excalidraw</strong> — §2.7.1, §2.7.2, C.4</td><td>613, 630, 1985</td><td><code>customData.clarae</code> (e la chiave di primo livello <code>clarae</code>): i client leggono anche <code>customData.memobrain</code>. Il limite accettato (un disegno toccato dal client nuovo perde su un 1.4.0 formule modificabili e ordine delle diapositive) merita una frase.</td></tr><tr><td><strong>Web Lock e dati nel browser</strong> — §1.7</td><td>284 (e 282, 288 per i nomi di pacchetto e wasm)</td><td><code>clarae-workbench</code>: la scheda nuova prende anche il lock vecchio (<code>memobrain-workbench</code>), così non convive con una scheda vecchia. I nomi di OPFS, IndexedDB e <code>/memobrain/data</code> non sono nello spec: se serve, descrivere la migrazione in §1.7.</td></tr><tr><td><strong>Feature flag</strong> — §2.6.6</td><td>579</td><td>Aggiungere <code>features.config_dir_v2</code> all&#39;elenco dei flag generati dallo schema (<code>api/config-profile.schema.json</code>): è un flag nuovo di M17 (C3), spento nella 1.5.0.</td></tr><tr><td><strong>Intestazione e registro delle revisioni</strong></td><td>7, 8, 9, 17–20</td><td>Riga 7: versione documento 1.6 con la nota «recepito ADR-0052». Riga 8: data. Riga 9: <code>*Clarae notanda* (identificatori </code>clarae<code>; già «MemoBrain Notes» e, come nome in codice, &quot;Nodus&quot;)</code>. Aggiungere una riga <strong>1.6</strong> al registro (in testa, prima della riga 17): le righe già presenti (17–20, che citano <code>.memobrain</code>, <code>@memobrain/…</code>, <code>memobrain-core</code>) sono cronologia e <strong>non</strong> si riscrivono.</td></tr><tr><td><strong>Stack e versione del prodotto</strong></td><td>tabella d&#39;intestazione</td><td>Opzionale: citare il payoff e la versione di prodotto 1.5.0 (lo spec non riporta oggi la versione del prodotto).</td></tr></tbody></table><p>Non servono modifiche a V-01…V-10 e D-01…D-08 per il nome: nessuna contiene <code>memobrain</code>. Il vincolo D-08 (redirect OIDC) e §1.3 cambiano solo per l&#39;elenco degli URI sopra.</p>',54)])])}const g=o(d,[["render",c]]);export{u as __pageData,g as default};
